use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl GlobWalkerBuilder { # [doc = " Construct a new `GlobWalker` with a glob pattern."] # [doc = ""] # [doc = " When iterated, the `base` directory will be recursively searched for paths"] # [doc = " matching `pattern`."] pub fn new < P , S > (base : P , pattern : S) -> Self where P : AsRef < Path > , S : AsRef < str > , { GlobWalkerBuilder :: from_patterns (base , & [pattern]) } # [doc = " Construct a new `GlobWalker` from a list of patterns."] # [doc = ""] # [doc = " When iterated, the `base` directory will be recursively searched for paths"] # [doc = " matching `patterns`."] pub fn from_patterns < P , S > (base : P , patterns : & [S]) -> Self where P : AsRef < Path > , S : AsRef < str > , { fn normalize_pattern < S : AsRef < str > > (pattern : S) -> String { if pattern . as_ref () == "*" { String :: from ("/*") } else { pattern . as_ref () . to_owned () } } GlobWalkerBuilder { root : base . as_ref () . into () , patterns : patterns . iter () . map (normalize_pattern) . collect :: < _ > () , walker : WalkDir :: new (base) , case_insensitive : false , file_type : None , } } # [doc = " Set the minimum depth of entries yielded by the iterator."] # [doc = ""] # [doc = " The smallest depth is `0` and always corresponds to the path given"] # [doc = " to the `new` function on this type. Its direct descendents have depth"] # [doc = " `1`, and their descendents have depth `2`, and so on."] pub fn min_depth (mut self , depth : usize) -> Self { self . walker = self . walker . min_depth (depth) ; self } # [doc = " Set the maximum depth of entries yield by the iterator."] # [doc = ""] # [doc = " The smallest depth is `0` and always corresponds to the path given"] # [doc = " to the `new` function on this type. Its direct descendents have depth"] # [doc = " `1`, and their descendents have depth `2`, and so on."] # [doc = ""] # [doc = " Note that this will not simply filter the entries of the iterator, but"] # [doc = " it will actually avoid descending into directories when the depth is"] # [doc = " exceeded."] pub fn max_depth (mut self , depth : usize) -> Self { self . walker = self . walker . max_depth (depth) ; self } # [doc = " Follow symbolic links. By default, this is disabled."] # [doc = ""] # [doc = " When `yes` is `true`, symbolic links are followed as if they were"] # [doc = " normal directories and files. If a symbolic link is broken or is"] # [doc = " involved in a loop, an error is yielded."] # [doc = ""] # [doc = " When enabled, the yielded [`DirEntry`] values represent the target of"] # [doc = " the link while the path corresponds to the link. See the [`DirEntry`]"] # [doc = " type for more details."] # [doc = ""] # [doc = " [`DirEntry`]: struct.DirEntry.html"] pub fn follow_links (mut self , yes : bool) -> Self { self . walker = self . walker . follow_links (yes) ; self } # [doc = " Set the maximum number of simultaneously open file descriptors used"] # [doc = " by the iterator."] # [doc = ""] # [doc = " `n` must be greater than or equal to `1`. If `n` is `0`, then it is set"] # [doc = " to `1` automatically. If this is not set, then it defaults to some"] # [doc = " reasonably low number."] # [doc = ""] # [doc = " This setting has no impact on the results yielded by the iterator"] # [doc = " (even when `n` is `1`). Instead, this setting represents a trade off"] # [doc = " between scarce resources (file descriptors) and memory. Namely, when"] # [doc = " the maximum number of file descriptors is reached and a new directory"] # [doc = " needs to be opened to continue iteration, then a previous directory"] # [doc = " handle is closed and has its unyielded entries stored in memory. In"] # [doc = " practice, this is a satisfying trade off because it scales with respect"] # [doc = " to the *depth* of your file tree. Therefore, low values (even `1`) are"] # [doc = " acceptable."] # [doc = ""] # [doc = " Note that this value does not impact the number of system calls made by"] # [doc = " an exhausted iterator."] # [doc = ""] # [doc = " # Platform behavior"] # [doc = ""] # [doc = " On Windows, if `follow_links` is enabled, then this limit is not"] # [doc = " respected. In particular, the maximum number of file descriptors opened"] # [doc = " is proportional to the depth of the directory tree traversed."] pub fn max_open (mut self , n : usize) -> Self { self . walker = self . walker . max_open (n) ; self } # [doc = " Set a function for sorting directory entries."] # [doc = ""] # [doc = " If a compare function is set, the resulting iterator will return all"] # [doc = " paths in sorted order. The compare function will be called to compare"] # [doc = " entries from the same directory."] pub fn sort_by < F > (mut self , cmp : F) -> Self where F : FnMut (& DirEntry , & DirEntry) -> Ordering + Send + Sync + 'static , { self . walker = self . walker . sort_by (cmp) ; self } # [doc = " Yield a directory's contents before the directory itself. By default,"] # [doc = " this is disabled."] # [doc = ""] # [doc = " When `yes` is `false` (as is the default), the directory is yielded"] # [doc = " before its contents are read. This is useful when, e.g. you want to"] # [doc = " skip processing of some directories."] # [doc = ""] # [doc = " When `yes` is `true`, the iterator yields the contents of a directory"] # [doc = " before yielding the directory itself. This is useful when, e.g. you"] # [doc = " want to recursively delete a directory."] pub fn contents_first (mut self , yes : bool) -> Self { self . walker = self . walker . contents_first (yes) ; self } # [doc = " Toggle whether the globs should be matched case insensitively or not."] # [doc = ""] # [doc = " This is disabled by default."] pub fn case_insensitive (mut self , yes : bool) -> Self { self . case_insensitive = yes ; self } # [doc = " Toggle filtering by file type."] # [doc = " `FileType` can be an OR of several types."] # [doc = ""] # [doc = " Note that not all file-types can be whitelisted by this filter (e.g. char-devices, fifos, etc.)"] pub fn file_type (mut self , file_type : FileType) -> Self { self . file_type = Some (file_type) ; self } # [doc = " Finalize and build a `GlobWalker` instance."] pub fn build (self) -> Result < GlobWalker , GlobError > { let mut builder = OverrideBuilder :: new (self . root) ; builder . case_insensitive (self . case_insensitive) . map_err (GlobError) ? ; for pattern in self . patterns { builder . add (pattern . as_ref ()) . map_err (GlobError) ? ; } Ok (GlobWalker { ignore : builder . build () . map_err (GlobError) ? , walker : self . walker . into_iter () , file_type_filter : self . file_type , }) } }
}